// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {RoundFactory} from "../src/RoundFactory.sol";

contract InvMutTest is Test {
    RoundFactory c;
    address deployer;

    function setUp() public {
        c = new RoundFactory();
        deployer = address(0xA11CE);
        vm.prank(deployer);
        c.initialize();
    }

    function testFuzz_property(address caller) public {
        vm.assume(caller != address(0));
        vm.assume(caller != deployer);
        vm.prank(caller);
        address reported = c.owner();
        assertTrue(reported == deployer && reported != tx.origin);
    }
}
